INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1022136-me218', 'stk-abu_abdullah', 'ME 218', 'info', '{"desc": "-\n\nكورس غثيث و يبي له وقت …\nلا تنخدع أنه ساعتين بس … لكن اللاب ياخذ منك وقت كبيير …\n\nتسوي 3 برزنتيشنات … و تستخدم السوليد ووركس في حل بعض الهومووركات …\nو أنصحك لاتصير قروب ليدر أبداً ههههههه …\n\nلأن القروب كله راح يرمي الشغل كله عليك وفي الأخير أنت اللي تشتغل وتكرف !!\n\nحاول تاخذ الكورس بددري … لأنة يفتح لك مواد مهمة لاحقاً … < راح يحدث تعديل على الخطة تقريباً و يصير الكورس يفتح الـ 307 + 322 + 309 … يعني مهم !\n\nقوود لك للجميع ❤️", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-218-introduction-to-me-design/120739/4", "user": "Abu_Abdullah", "ts": 1334402506000, "tid": 120739, "pn": 4}}', 1334402506000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1162517-me218', 'stk-user5430', 'ME 218', 'info', '{"desc": "الوضع تغير الترم هذا 🌹\n\nعموما المادة فيها تعب , و فيها متعه\nالتعب يكون بأول الاسابيع لان يكون فيها اشياء نظرية\nوالمتعه تكون في اخر شهر تصيرون تشتغلون على تصاميمكم\n\nمن ناحية القريدات … اهم شي اهم شي لا تنكسر بيضتكم !\nوضبط كويزآتك و شغلك باللاب , وتطلع فيها بـ A 🤠\n\nونصيحة : نزل اللاب عند بيق 🤠", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-218-introduction-to-me-design/120739/8", "user": "user5430", "ts": 1357944678000, "tid": 120739, "pn": 8}}', 1357944678000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1228973-me218', 'stk-s2010xxxxx', 'ME 218', 'info', '{"desc": "نصيييحه لا تضيع ولا درجه مهما كانت بسيطه , برزنتيشن او تقييم دفتر او اي شي لا تضيعه , والاختبارات اللي باللكتشر عليها شي كثير حاول تجيب فيها كامل وحاول تتعاون مع قروبك لان الدرجات بتتقسم بينكم في اغلب الاوقات… اللكتشر ما منها فايده لكن اعيد واكرر لا تضيع الكوزات حقتها وراح تلقى الماده ممتعه باخر الاسابيع يوم تبدون تسوون اللانشر والكارير حقتكم اما بالبداية راح تكون ممله نوعا ما وموفقين", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-218-introduction-to-me-design/120739/14", "user": "s2010xxxxx", "ts": 1369689753000, "tid": 120739, "pn": 14}}', 1369689753000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1309971-me218', 'stk-h3keem', 'ME 218', 'info', '{"desc": "زبدة الكورس انك انت وكم شخص تسوين شيء يقذف شيء ثاني داخله بيضه\nتقدر تسوي ذا الشيء في يوم واحد لكن الاغلب يتفلسف و يجيب افكار مو عملية وفي الاخير تنكسر البيضة 🙂\n\nما اقولك لا تبدع بالعكس لكن حاول تكون واقعي\n\nالكوزات اغلبها حفظ وعليها كثير تقريبا 20 %\n\nما في سولد ورك الا لهموركين بس", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-218-introduction-to-me-design/120739/17", "user": "h3keem", "ts": 1388079413000, "tid": 120739, "pn": 17}}', 1388079413000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1311994-me218', 'stk-abo_ali', 'ME 218', 'info', '{"desc": "معك بالاحمر , 👍\n\nلك بالاخضر\n3 واجبات + التصميم النهائي لللانشر والكاريير بالسوليد ووركس\nيعني لازم تكون فاهم كيف تسوي حاجات والاسمبلي وكذا علشان تاخذ الدرجه الزينه", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-218-introduction-to-me-design/120739/19", "user": "Abo_Ali", "ts": 1388422253000, "tid": 120739, "pn": 19}}', 1388422253000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1372700-me218', 'stk-nice_day', 'ME 218', 'info', '{"desc": "المادة مثل ماقالو الاخوان قبل\n\nتعريف بقطع بسيطة تساعدك انك تعمل حاجه بسيطة مثل قذف البيضة\n\nالقريد :\n\nاهتم بالبدايات من اول كلاسات , و اعتبر نفسك طفل تلعب عادي جدا\n\nيعني مثلا بالبداية لما يقولو لك ارسم افكار لانك تحذف البيضة , و انهم مايهمهم ايش الفكره\n\nخربط يعني ع العدد بتاخذ قريد لو ترسم بس ياخذ بيضة ويوديها\n\nو لاتستهين بالنوت بوك لما يقولو لك اكتب لنا ايش سويت بالمحاضرات واعطينا النوت بوك نقيمك ( 15 درجة )\n\nخربط عادي سولف اللي تبي بس مهم جدا اي شي سويته دبسه في النوت بوك واذا مو معك ارسمه واكتبه ع كثرة الاغراض اللي تحطها تاخذ الدرجة\n\nوبالاخير للمشروع افضل انك تقلد ناس اخذو من قبل وتختصر الوقت وانصحك اذا الابداع راح يكلفك وقت لاتهتم فيه\n\nلان الملاحظ بالمادة ماهي جودتك كمهندس انما والله مدري ماهو واضح بس اعتقد يبون يشوفون وش تعلمت ويبونك تكتب لهم وتوريهم هالشي\nولاتستهين بشي ابد لو درجة قليله\n\nبالاخير : اهم شي انك تنجز كل حاجه مطلوبه منك , ومو مهم الزيادات ابدا\n\nالكوزات جدا مهمه عليها بعض الاحيان 20 درجة\n\nتحياتي", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-218-introduction-to-me-design/120739/25", "user": "Nice_day", "ts": 1401208763000, "tid": 120739, "pn": 25}}', 1401208763000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1438146-me218', 'stk-dyaa94', 'ME 218', 'info', '{"desc": "البروجكت تغير ذا السمستر 151…ناس اخذت البيضه واكثر الناس اخذو السياره ((تصمم قارب وسياره…القارب يمشي مسافه وبعدين السياره تكمل للTarget )) ومشروع السياره كان اصعب…\n\nطبعا مو باختيارك…حظك وش يطلع لك واتوقع راح يكون في المستقبل مشروع واحد السياره بسس\n\nالكورس جدا مفيد للمهندس الميكانيكي راح تتعلم كثير عن الdesign process\n\nمن اكثر الكورسات اللي استفدت منها\n\nوالقريد مو صعب فيها\n\nبالتوفيق…", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-218-introduction-to-me-design/120739/26", "user": "Dyaa94", "ts": 1452075257000, "tid": 120739, "pn": 26}}', 1452075257000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1480222-me218', 'stk-m_nd_m', 'ME 218', 'info', '{"desc": "جودة المقرر بشكل عام\nجودة المقرر ممتازة و أشوف أنه كورس مهم… للأسف بعض الشباب كان يصف الكورس بأنه كورس “بزران” …؟!\nوهو بالحقيقة كورس مهندس\n\nالمواضيع التي يغطيها المقرر\nبإختصار الكورس يعلمك كيف تستلم مشروع من الـ أ إلى الـ ي… بالإضافة لبعض الأخلاق التي يجب أن يتحلى بها المهندس (Engineering Ethics)\nو أنت شخصيًا ستقوم باستلام مشروع و هو تصميم مركبة تمشي 4 امتار على الماء و 8 أمتار على اليابسة بدون تدخل منك\n\nالكتاب المستخدم للمقرر\nلا يوجد كتاب يؤخذ من مكتبة الكتاب لكن الكتاب يرفع على البلاكبورد (نادر تستخدمه خلال الكورس) بالإضافة لسلايدات للكتشر و اللاب\nالأسئلة والأمثلة المستخدمة في المقرر\n\nمدى فائدته في الناحية التطبيقية\nمفيد جدًا… بتستخدم كل القوانين و التحليلات اللي درستها خلال سنوات دراستك خصوصًا في ما يخص الـestimation و اختيار الشكل المناسب لمركتبك\nهذه عينة من الإستميشن:\n\nإضافات مهمة/\nالمادة مافيها مياجر ولا فاينل\n\nاللكتشر ساعة أسبوعيًا يقدمها الدكتور مراح و مبين… الأفضل مبين من بينهم لكن إذا انحديت على مراح مو مشكلة بس شد حيلك أكثر بالهوموركات و الكويزات و تطلع بقريد طيب ان شاء الله\n\nاللاب ثلاث ساعات أسبوعيًا… قد تزيد في آخر الأسابيع على أساس تسطيع الفرق تنهي مشروعها بالكامل… أفضل الدكاترة كما يقال الدكتور عبدالعظيم و فعلًا الدكتور ذكي جدًا و فاهم المادة زين (تعاملت معه كم مرة)… شخصيًا أخذتها عند ماجد لنجاوي و كان ممتاز بكل شي بس كريف\nأفرج اللاب 60/75 و الـ25 الباقية من اللكتشر\nممنوع الثوب باللاب طبعًا\nلا يوجد لاب أول أسبوع\n\nعلى آخر السمستر في مسابقة تقام بالقاعة الوسطى بمبنى 63 مدتها تقريبًا ساعتين و نص-ثلاث ساعات و نسبة كبيرة من درجات اللاب تعتمد على نجاح المركبة في هذه المسابقة… أيضًا يوجد بوستر يجب أن يحتوي على أغلب معلومات المشروع\nhttps://f.top4top.net/p_621tj0zd1.jpeg\nفي نوت بوك كل مجموعة لازم تسويه… المجموعة مكونة من 5 أفراد عشوائيًا يقوم كل فرد باستلام 3 أسابيع يلخص فيها كل ما أنجزه الفريق خلالها (نصيحة لحد يمسك آخر أسبوع تراه كرف 🤠)\n\nتوزيع الدرجات/\nالتوزيع هذا من اللي استنتجته و لاحظته من درجات الشباب\n\n78 C+\n80 B\n82 B+\n84 A\n\nو هكذا… تقريبًا كل درجتين بقريد… لذا أنصح الجميع بعدم الاستهانة بأي هومورك أو كويز لأنه كل درجة تفرق !\n\nبالكورس هذا بتستخدم أكثر من برنامج (سولد وركس باور بوينت مايكروسوفت اكسل)\n\nالمادة فيها على الأقل تقديم عرض مرتين و أحيانا ثلاث على حسب الدكتور… شخصيًا قدمت عرض فردي (بدون باوربوينت) و مرتين جماعي (مع باوربوينت) مرة بنصف السمستر\n\nنصائح متنوعة بخصوص المشروع/\nلا توقف شغل لين تبدأ المسابقة ! فريقنا ما خلص المركبة و ما جهزت إلا قبل المسابقة بدقائق و الحمدلله نجحت نجاح مفاجئ للأمانة (فرحة لا توصف يومها هههههههههههههههه)\nبعد ما تنتهي من بناء مركبتك بكون أغلب شغلك عبارة عن Trial&Error يعني بتقعد تجرب أكثر من شي لين توصل “للوصفة السحرية” و بتلاحظ أيضًا علاقات غريبة يعني ممكن تزيد الوزن حق المركبة تصير تمشي مسافة أطول !\n\nملف مهم يشمل سلايدات اللكتشر و اللاب و الكتاب و كويزات و هوموركات و السيلابس و و و و و و\nME218 - STKFUPM&RESOURCES | تحميل\n\nصورة تلخص المهمة التي يجب أن تنجزها مركبتك\n\n***اللي حاب يعرف أكثر عن الكورس حمل الملف و تصفح السلايدات و الملاحظات و الصور و إن شاء الله ما أكون نسيت شي و أعتذر عن الأخطاء الإملائية إن وجدت", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-218-introduction-to-me-design/120739/27", "user": "M_nd_m", "ts": 1505295592000, "tid": 120739, "pn": 27}}', 1505295592000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1522396-me218', 'stk-nasalmz', 'ME 218', 'info', '{"desc": "term 192\n\nجائحة كورونا خلت الكورس كريه وقلبته انقلش 102 صار كله ريبورتات.\n\nطبعا الكورس والله ما تدري وش محلك الاعرابي الا ف الاخير بس نصيحه انتبه ترا كل لاب عليه درجات تقريبا 4 بالميه ويمكن توصل 7 بالميه ف انتبه تغيب و القروب بيكون عشوائي انت وحظك يمكن قروب ممتاز او قروب ضايع", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-218-introduction-to-me-design/120739/28", "user": "Nasalmz", "ts": 1590430177000, "tid": 120739, "pn": 28}}', 1590430177000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1530168-me218', 'stk-abofordan2004', 'ME 218', 'info', '{"desc": "TERM 202 ONLINE\n\nمادة شفتها تافهه لابعد حد للامانة بالنسبة للكتشر فهو سواليف وعن نفسي ما كنت اركز فيها لان فعلا ما لها اي فايدة الشغل كله في اللاب\n\nاول 10 اسابيع بيجلس يشرح لك المدرس كيف تجهز للمشروع النهائي اللي هو زبدة المادة والمشروع عبارة عن تصميم جهاز يحذف كورة الى بعد 2 متر عند ارتفاعه الى 75 سانتي ( لا تخاف جدا سهل ) المشروع بكبرة اسبوع يكفيه لكن هم الله يهديهم ماغطينها الى 15 اسبوع .\n\nبالنسبة للدرجات كل لاب عليه 2% او 3% , اهم شيء لا تستهين في اي درجة باللاب مهما كانت ال Assignment تافهه وصدقني بيكون القريد سهل\n\nطبعا لا يوجد فيها ميد ولا ميجر ولا حتى فاينل و توزيع الدرجات 75% لاب و 25% لكتشر", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-218-introduction-to-me-design/120739/29", "user": "AboFordan2004", "ts": 1622374199000, "tid": 120739, "pn": 29}}', 1622374199000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-heisenberg-me218', 'stk-heisenberg', 'ME 218', 'doc', '{"docs": [{"id": "stk-dr-f98212", "n": "Dr. Neçar Merah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "me218 152\nلتحضير :يمرر ورقة\nطريقة الشرح :من السلايدات\nالكويزات :سهلة\nالقريد النهائي:c+\nالصوت:واضح\nإضافات :الدكتور فاهم ويشجع الطلاب لكن لما ينتقدك يحسسك كانه يبي يتهاوش معاك كانك بزر عنده وتحس انه شايف نفسه ماراح تفهم كلامي الى اذا جاكم يقيم. بصراحة ماراق لي ابد لان فصل على واحد من قروب بس لانه كان ياكل علك واحرجه قدام الطلاب علشان علك !!!!( لاتاخذ بكلامي لانه ماحد عاملني في الجامعة باسلوبة ابد )", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1449271-me218", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/prof-necar-merah/98212/11", "user": "HEISENBERG", "ts": 1463438615000, "tid": 98212, "pn": 11}}]}', 1463438615000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdelaziz-me218', 'stk-abdelaziz', 'ME 218', 'doc', '{"docs": [{"id": "stk-dr-f98212", "n": "Dr. Neçar Merah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Me 218 lecture - 152\n\nالتحضير : يمرر ورقة وانت وحظك توصلك ولا لا لان القاعة كبيرة، لو خليت احد ثاني يحضرك مادرى عنك.\n\nطريقة الشرح :\nمن السلايدات وشرحه جيد نوعاً ما.\n\nالكويزات :\nسهله من السلايدات مباشرة.\n\nالمياجر: مافيه\n\nالفاينلات :\nمافيه\n\nالقريد النهائي:\nB\n\nالصوت:\nواضح جداً\n\nإضافات :\nمايسمح بالتأخير أبداً\nوتقسيم قريداته مادري كيف بصراحه\n85 a\n82 b+\n76 c !!!", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1450572-me218", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/prof-necar-merah/98212/12", "user": "Abdelaziz", "ts": 1464435646000, "tid": 98212, "pn": 12}}]}', 1464435646000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-owheading-me218', 'stk-owheading', 'ME 218', 'doc', '{"docs": [{"id": "stk-dr-f98212", "n": "Dr. Neçar Merah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME218 TERM 181- ME307 TERM 191\n\nالتحضير :\nنهاية الكلاس في العادة وبعض الأحيان ينسى\nطريقة الشرح : بالسلايدات وقليل إذا كتب شيء ع السبورة، شرحه أشوف ضعيف وغير كافي\nالكويزات :\nمتوسطة مايلة للصعوبة\nالمياجر والفاينلات:\ncommon وتصحيحه سيء\nالقريد النهائي: C+\nالصوت: واضح\nإضافات :\nليس الأفضل في التدريس، التعامل حسب المزاج، الشرح ضعيف والتصحيح سيء، لو رجع بي الزمن ما درست عنده", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1522445-me218", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/prof-necar-merah/98212/15", "user": "OWHEADING", "ts": 1590690151000, "tid": 98212, "pn": 15}}]}', 1590690151000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-pink_panther1-me218', 'stk-pink_panther1', 'ME 218', 'doc', '{"docs": [{"id": "stk-dr-f98212", "n": "Dr. Neçar Merah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME 218 - Lecture - 192 (Covid-19)\n\nالتحضير :\nيحضر عن طريق البلاك بورد، أحيانا عن طريق الclass activities او الquizzes او يكتب كود تحضير\nمايسمح بالتأخير(اذا جيت متأخر ما يدخلك)\n\nطريقة الشرح :\nعن طريق السلايدات حقته\n\nالكويزات :\nسهلة وواضحة ومن السلايدات نفسها\n\nالقريد النهائي:\nA\n\nالصوت:\nعادي\n\nإضافات :\n- المادة بدون مياجر وفاينلات.\n- 25% من درجة المادة للكتشر والباقي للاب (75%).\n- الدكتور ما يسمح بالتأخير.\n- الدكتور ما يسمح باستخدام الجوال، ويزعل اذا شاف احد عالجوال.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1522675-me218", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/prof-necar-merah/98212/16", "user": "Pink_Panther1", "ts": 1591349103000, "tid": 98212, "pn": 16}}]}', 1591349103000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abo_yazeed6-me218', 'stk-abo_yazeed6', 'ME 218', 'doc', '{"docs": [{"id": "stk-dr-f98225", "n": "Dr. Mohammad Anis", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "انا اخذت معه me 218 وما انصح فيه بهذي المادة لسببين:\n\n1-دايم يفاجئنا وما يعطينا خبر عن الأشياء الي المفروض نسلمها,مرة في نشاط معين طلب منا نسوي جدول ونعبيه بمعلومات ,الشاهد انا قلنا له بنسوي الجدول بطريقة معينة ووافق ,ثم جاء آخر اللاب وقال لنا انا ما قلت لكم شي وخسف فينا بالدرجات,مرة يقولنا انا طلبت منكم تسوون كذا وكذا في البريسنتيشن ,وما كان قايل لنا شي ,واشياء كثيرة غيرها,الزبدة انه عنده مشكلة في ذاكرته.\n\n2-أشياء كثيرة ما يشرحها بطريقة مفهومة ,يعني نحتاج مرة ومرتين وثلاث وأحيانا أكثر انه يعيد لنا المطلوب عشان نفهم ايش يبغى بالضبط.\n\nما عدى ذلك الرجال طيب ومتسامح ويحاول يساعدك باللي يقدر عليه.\n\nخله كخيار ثاني.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1383046-me218", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-mohammad-anis/98225/13", "user": "abo_yazeed6", "ts": 1403887980000, "tid": 98225, "pn": 13}}]}', 1403887980000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-guest-me218', 'stk-guest', 'ME 218', 'doc', '{"docs": [{"id": "stk-dr-f98225", "n": "Dr. Mohammad Anis", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME218 - T211\n\nالتحضير:\nيحضر نهاية اللاب.\n\nطريقة الشرح :\nفيه سلايدات للاب يشرحها وشرحه جدًا ممل ويجيب النوم وأغلب الوقت ما تفهم منه.\n\nالتصحيح:\nهبد بشكل مو طبيعي! مرات يرفعك ومرات يخسفك.\n\nالكويزات :\nكان فيه كويز واحد في نهاية السمستر.\n\nالمياجر:\nما فيه مياجر ولا فاينلات للمادة.\n\nالصوت:\nهادي شوي بس تفهم عليه.\n\nإضافات:\nالدكتور متعاون خارج وقت اللاب بس في اللاب أغلب الوقت يضيعك لو تسأله عن شيء، والدكتور ينسى كثير لازم تحرص عليه اذا بغيت شيء منه.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533394-me218", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-mohammad-anis/98225/22", "user": "Guest", "ts": 1641844237000, "tid": 98225, "pn": 22}}]}', 1641844237000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-turky_al-dossary-me218', 'stk-turky_al-dossary', 'ME 218', 'doc', '{"docs": [{"id": "stk-dr-f98247", "n": "Dr. Mirza Murtuza Ali Baig", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "~~~~ ME- 218-/LAB … Term: 121 ~~~~\n\nالتحضير :\n\nينادي بالاسماء بعد اول 10 دقايق\n\nطريقة الشرح :\n\nسلايدات يقراها ،، لانه ما فيها شيء المادة\n\nإضافات :\n\nمدرس خلوق ،، ومتعجب لكلام اللي فوق 🤪 ،،، متواضع متفهم للطلاب\n\nيعني لي مواقف مع المدرس الفصل هذا وما قصر ،،\n\nاتوقع انه افضل من الدكاتره ،، بس احتمال اذا مدرس اللاب هو مدرس الكتشر فاذا شافك تكرف في اللاب زبطك في القريد\n___________________________________________\n\nاي سؤال ،، لا يردك الا رسالة خاصة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1162348-me218", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-mirza-murtuza-ali-baig/98247/7", "user": "Turky_Al-Dossary", "ts": 1357927308000, "tid": 98247, "pn": 7}}]}', 1357927308000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdullatif1994-me218', 'stk-abdullatif1994', 'ME 218', 'doc', '{"docs": [{"id": "stk-dr-f98247", "n": "Dr. Mirza Murtuza Ali Baig", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME218 LAB Term141\n\nالتحضير :\nيحضر كل لاب من بدايته …\n\nطريقة الشرح :\nالمادة ماتوقع فيها شرح سنع …\n\nالكويزات : None\n\nالمياجر: None\n\nالفاينلات : None\n\nالقريد النهائي: B\n\nالصوت: واضح لكن مو عالي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1420412-me218", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-mirza-murtuza-ali-baig/98247/14", "user": "Abdullatif1994", "ts": 1421613987000, "tid": 98247, "pn": 14}}]}', 1421613987000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-obsessions-me218', 'stk-obsessions', 'ME 218', 'doc', '{"docs": [{"id": "stk-dr-f175787", "n": "Dr. Majid Linjawi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "افضل واحد في ME 218 بلا منازع نزلت معه الترم اللي راح وعطاني قريد افضل مماتوقعته بالاضافة يحسسك انه واحد من اخوياك لانه لازال شاب\nالشرح ممتاز يعطيك الزبدة بدون لف ودوران ويتكلم عربي اغلب الوقت ومتساهل في تسليم الواجبات مع ان اللاب غثيث بس ماتحس به معه\nالتحضير انا دايما اجيه بعد 10 دقايق ولايدقق\nاقولها من الاخر لاتنزل اللاب الا معه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1472027-me218", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/majid-linjawi/175787/2", "user": "obsessions", "ts": 1493148473000, "tid": 175787, "pn": 2}}]}', 1493148473000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-m.n.a-me218', 'stk-m.n.a', 'ME 218', 'doc', '{"docs": [{"id": "stk-dr-f175787", "n": "Dr. Majid Linjawi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME 218 LAB TERM 162\n\nالتحضير : اول الكلاس و ما يدقق على التاخير اذا كانت عشر دقايق مثلا\n\nطريقة الشرح : يكون اول ربع ساعة وما يطول فيه و اسلوبة خفيف ما يخليك تمل مع ان المادة تغث\n\nالصوت: واضح و يتكلم اغلب الوقت بالعربي.\n\nإضافات : انا اشوف الدكتور نسبيا كريف , دايماعنده تعليقات على شغلك مهما كان دايما في احسن بالنسبة له. بس في الاخير رفعنا كلنا بالدرجات اللافرج عنده كان 80%\nفي الاخير انصح بالدكتور و يعتبر من الافضل في هذا الكورس الغثيث لاكثر من سبب:\nالدكتور حبيب و متعان لابعد درجة و اذا جبت العيد في شي ممكن يخليك تعيده بعد ما يعطيك ملاحظاته و يحسن لك الدرجة و في البروجيكت يساعدك ويعطيك افكار و حلول.\nدرجاته جدا ممتازة و يكفي انه وقت اللاب معه يعدي وما تحس فيه.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1474939-me218", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/majid-linjawi/175787/4", "user": "M.N.A", "ts": 1497204258000, "tid": 175787, "pn": 4}}, {"id": "stk-dr-f175788", "n": "Dr. Mobeen Shaukat", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME 218 TERM 162\n\nالتحضير : اخر الكلاس يحضر بالاسم و يسجل بالبلاك بورد\nطريقة الشرح : يستخدم سلايدات و فيديوهات طريقته ممتعة مع ان المادة سخيفة الا انك تستمتع فيها معه\nالكويزات : تافهة جدا و الواجبات قليلة وبسيطة جدا وهذه ميزة وعيب\nالمياجرو الفاينلات : لا يوجد\nالصوت: واضح و الاكسنت مفهومة الى حد كبير\nإضافات : الدكتور طيب جدا جدا و كلاسه ممتع وما تشيل هم الكورس معه لكن اذا انت طالب تبغى قريد ما انصحك فيه\nطيبة الدكتورو كويزاته و واجباته السهلة تساوي بين المجتهد و اللي ما يشتغل و الافرج كان جدا عالي وصار اللي يفرق درجة اللاب لان كله تقريبا فل في الكلاس وورك وانا اشوفه شي ظالم لان دكاترة اللاب تختلف بعضهم كريم وبعضهم شديد.\nالمختصر اذا انت مجتهد و تبي قريد في هذا الكورس ماانصح فيه ابدا\nاذا تبي الكورس يكون خفيف و ما تشيل همه و ما يفرق معك القريد نزل معه وانت مغمض.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1474947-me218", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mobeen-shaukat/175788/2", "user": "M.N.A", "ts": 1497210776000, "tid": 175788, "pn": 2}}]}', 1497204258000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-m_nd_m-me218', 'stk-m_nd_m', 'ME 218', 'doc', '{"docs": [{"id": "stk-dr-f175787", "n": "Dr. Majid Linjawi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME218 Lab - T162\n\nالتحضير : بداية الكلاس ماعنده مشكلة تتأخر شوي… و للأمانة بعض الشباب بالجروب و أنا منهم كانت تروح علينا نومة بعض المرات و نجي يمشيها لنا ما يقولنا شي\n\nطريقة الشرح : عنده سلايدات يشرح منها مباشرة… و أحيانًا:\nيستخدم السبورة إذا الشغلة فيها حسابات\nيستخدم بعض الأدوات لتوضيح فكرة أو طريقة استخدام\nأحيانًا يكون في Team activity\nالزبدة الدكتور فاهم و متمكن جدًا بالمادة خصوصًا أنه عنده تجربة ممتازة مع سيارة وهج\nاللي ما يدري وش قصة وهج، هذه هي:\nوهج1\n\nyoutube.com - YouTube\n\nAuf YouTube findest du die angesagtesten Videos und Tracks. Außerdem kannst du eigene Inhalte hochladen und mit Freunden oder gleich der ganzen Welt teilen.\n\nوهج2\n\nو رغم هذا تجده متواضع جدًا ولا مرة جاب طاري الموضوع… الزبدة كأني شطحت شوي 🤠\n\nالكويزات : لا يوجد\n\nالمياجر: لا يوجد\n\nالفاينلات : لا يوجد\n\nالقريد النهائي: أتركه لكم\n\nالصوت: واضح جدًا\n\nإضافات :\n\nالشرح ممتاز\nحبيب و متعاون\nفاهم المادة بجميع نواحيها (من فكرة لاستخدام الأدوات الخ الخ)\nبحاول يعطينا وقت إضافي قدر المستطاع\nاللاب الافرج فيه 60 من 75… الدكتور يعطيه العافية حاول يدفنا أكثر شي (الدرجات مرفقة)\n\nكــــــــــــــــــــــــــــــــــــــــــريــــــــــــــــــــــــــــــــــــــــــــــــــــــــــف\nأحيانًا يتأخر برفع بعض الملفات (مثلًا السلايدات)\nماعنده أوفيس أورز ثابتة و إذا تواصلت معه و حددت معه موعد ما يجي (لظرف عنده) لكن أعطينا خبر الله يهديك\n\nفي ملف شامل للمادة رفعته على الـResources من فترة و أيضًا موجود بموضوع تقييم المادة\n\nإن شاء الله ما نسيت شي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1481787-me218", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/majid-linjawi/175787/5", "user": "M_nd_m", "ts": 1507889017000, "tid": 175787, "pn": 5}}]}', 1507889017000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mohammedj-me218', 'stk-mohammedj', 'ME 218', 'doc', '{"docs": [{"id": "stk-dr-f175788", "n": "Dr. Mobeen Shaukat", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME 218 TERM 172\n\nالتحضير : اخر الكلاس يحضر بكوز على البلاكبورد, يعطيك إجابة الكويز وانت بس تدخل وتحط الاجابة وخلاص انت حاضر.\nطريقة الشرح : سلايدات وفيديوات, ترا المادة سخيفه يعني ما يهم الشرح.\nالكويزات : سهلة, مذاكرة ابو ساعة قبل الكويز وكنت اجيب درجات كويسة.\nالمياجرو الفاينلات : لا يوجد\nالصوت: واضح\nإضافات :\n- عطانا غيابين بدون غصم.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1492616-me218", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mobeen-shaukat/175788/4", "user": "mohammedj", "ts": 1526575665000, "tid": 175788, "pn": 4}}]}', 1526575665000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-trad-me218', 'stk-trad', 'ME 218', 'doc', '{"docs": [{"id": "stk-dr-f175788", "n": "Dr. Mobeen Shaukat", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "(ME218 Term 201 (Online\n\nالتحضير :\nكان يسوي لنا Attendance Quiz نهاية المحاضرة, طبعا مايهم جاوبت صح او غلط المهم انه تاخذه\n\nطريقة الشرح :\nيشرح على السلايدات واحيانا يعطيك كم معلومة برا السلايدات , طبعا السلايدات اغلبها كلام وينحفظ وفيه حسابات بسيطة جدا متعلقة بالمفاهيم\n\nالكويزات :\nعطانا خمس كويزات والاخير كان هدية ,طبعا هو قال لنا بداية السمستر ان الكويزات بتكون صعبة بحكم ان الوضع اونلاين واغلب الطلاب بيغشون فكانت كويزاته فيها صعوبة نوع ما لانه كان يجيب كم سوال من برا السلايدات.\nالمياجر:\nلايوجد\n\nالفاينلات :\nلا يوجد\n\nالصوت: واضح لاباس به\n\nالقريد النهائي: A\n\nإضافات\nالدكتور خلوق جدا ومتعاون مع الطلاب بشكل كبير وماكان يراقب علينا وقت الكويزات", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527557-me218", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mobeen-shaukat/175788/9", "user": "Trad", "ts": 1609776423000, "tid": 175788, "pn": 9}}]}', 1609776423000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-omar_ali_bajabaau-me218', 'stk-omar_ali_bajabaau', 'ME 218', 'doc', '{"docs": [{"id": "stk-dr-f175788", "n": "Dr. Mobeen Shaukat", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME 218 - TERM 201\n(Online)\n\nالتحضير : يحط Attendance quiz على البلاكبورد ومو مهم انك تختار الاجابة صح او خطا، اهم شيء تجاوب وبيحسبلك حضور.\n\nطريقة الشرح : عن طريق سلايداته ويشرح على البلاكبورد وشرحه مفهوم واحسه شوية سريع في الشرح ويجيب احيانا اسئلة وفيديوهات تعزز الشرح ويسال الطلاب ويبغاهم يفكروا ويسمع اراءهم في نفس الوقت ويحفز المشاركة.\n\nالتصحيح: تصحيحه صراحة مافهمته لانه بيصحح الواجبات بس لانه الكويزات عن طريق البلاكبورد اختياري، وبناء على درجاتي في الواجبات اشوف تصحيحه لا باس فيه.\n\nالكويزات : غالبا اختياري سهل على البلاكبورد.\n\nالمياجر: لا يوجد\n\nالفاينلات : لايوجد\n\nالصوت: صوته جدا واضح\n\nإضافات : الدكتور طيب وحبوب وتحسه يعطيك طاقة لما يبدا يشرح من السرعة والحماس الي هو فيه. اشوفه بالمجمل كويس لكن ماعرف كيف بيكون في المواد الثانية، لكن انصح فيه في ذي المادة (ME218", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527716-me218", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mobeen-shaukat/175788/10", "user": "Omar_Ali_BajabaaU", "ts": 1610178216000, "tid": 175788, "pn": 10}}]}', 1610178216000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-moh_ammed-me218', 'stk-moh_ammed', 'ME 218', 'doc', '{"docs": [{"id": "stk-dr-f175788", "n": "Dr. Mobeen Shaukat", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME 218 (LEC) - Term 212\nالتحضير: يفتح اساينمت للتحضير في البلاكبورد في نهاية المحاضرة ويكون منه التحضير، لكن إذا كان عندنا كويز يكون الكويز مكان التحضير (والكويز يكون نهاية المحاضرة أيضا).\nماعنده ليت، بس بنهاية الترم قعد يحثنا بالحضور وعدم التأخر لأن بعض الطلاب مصخوها بالتأخير.\n\nالشرح: الدكتور شرحه كويس ويشرح على طبيعته ومايتكلف في الشرح، وأحيانا الوضع ينقلب مشاركة ومناقشة بين الدكتور والطلاب لأن الدكتور أصلا يحب الطلاب يشاركون معه بالشرح… والوضع يصير ممتع للأمانة بهذي الطريقة.\n\nالتعامل: الدكتور عسل ولطيف جدا بتعامله.\n\nالصوت: واضح، بس لو كانت اللهجة أوضح شوي كان أفضل…أتوقع أنه باكستاني.\n\nالكويزات: أنا ذاكرت للكويز الأول فقط وجبت فل، أما باقي الكويزات كنت أخش بدون مذاكرة وكنت أجيب درجات حلوة…يبي لك بس تركز معه في الشرح. أخذنا 5 كويزات -على ما أذكر- وحذف منها الأسوأ.\n\nإضافات: المادة ماهي طويلة ومايبغى لها ذاك الشيء، فلذلك كثير من المحاضرات كنا نطلع قبل انتهاء وقت المحاضرة بفترة. والمادة كذلك مافيها لامياجر ولافاينل فتعتبر مادة خفيفة.\n\nالدكتور عموما أنصح فيه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1534559-me218", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mobeen-shaukat/175788/12", "user": "Moh_ammed", "ts": 1654354200000, "tid": 175788, "pn": 12}}]}', 1654354200000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-test101-me218', 'stk-test101', 'ME 218', 'doc', '{"docs": [{"id": "stk-dr-f185062", "n": "Dr. Usman Ali", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME 218- 211:\n\nبنود التقييم :\n\nالتحضير : بداية الترم كان يحضر عن طريق انه يفتح كويز نهاية المحاضرة الكويز ممكن يكون واحد من الكويزات المحددة خلال الترم وعليها وزن ٣-٥٪؜ او كويز تحضير جوابه بسيط. بحكم انه اول ترم للدكتور يدرس المادة ما كان مدقق على الحضور الى فترة المياجر لما صار يلاحظ ان الغايبين واجد و محضرين انفسهم بالكويز، فوقتها صار يقول للطلاب بالكلاس بفتح كويز تحضير ولا تعبونه اللي يعبيه غايب. وبعد فترة صار يوزع ورقة ويخلي الطلاب يكتبون اساميهم والايدي ويوقعون. نهاية الترم حط كويز تحضير بونص وكان السؤال هل انت طالب ساينس او ابلايد.\n\nطريقة الشرح : يقرا سلايدات الكورس و يعطي قصص وتوضيحات بسيطة. احيانا يقول امثلة على بعض الاشياء ويجيبها بالكويز.\n\nالكويزات : بترمنا كانت الكويزات كلها على البلاكبورد ( تغير بعدها) و كان مشدد على عدم الغش لكنه يساعد :).\n\nالمياجر: لا يوجد مياجر\nالفاينلات : لا يوجد\nالقريد النهائي: A\nالصوت: ضعيف شوي واللهجة احيانا غير مفهومة.\n\nإضافات :\nكما ذكرت كانت اول مره للدكتور يدرس الكورس واعتقد والله اعلم اول ترم حضوري بالكامل له بالجامعة، فكثير من الامور تغيرت خلال الترم وبالاترام اللي بعدها. الدكتور حبيب ومتعاون واللي بيده كله على بعضه من الكورس ٢٥٪؜ الباقي على اللاب. من ناحية قريدات بنهاية الترم كان افضل من مبين ( دكتورين كانوا يدرسون المحاضرة بذاك الترم).\nجاءنا بالبرزنتيشن حقت اللاب كمقيم وكان غير مبالي ومو مركز ( على جواله) وسلك لنا بتعليقات بسيطة زي ان الخط بالسلايدات لازم يكون كبير وواضح وان الطالب لازم يلبس لبس متناسق يعني مثلا لابس ثوب لا تلبس معاه قبوع يا تلبس شماغ او بدون ولا تحطون اياديكم في جيوبكم، ما كان عنده اي تعليق على الشغل والمشروع نفسه على عكس مبين اللي كان يركز مع المجموعات الثانيه على الحسابات و الخ. وهذي طبيعة الدكتور عثمان باي كورس، اذا قدمت برزنتيشن بيركز على الامور التالية:-\nDress\nFont size\nPictures size and clarity\nReferences\nBehavior during presentation\nما يدقق كثير على المضمون العلمي.\n\nطبعا الدكتور كان يكرر من كويزات الresources حقت الدكاترة الثانيين و يزيد عليها من عنده من امثلته وغيرها. كان ذا الشيء يميزه عن مبين لان مبين كان اغلب الوقت يكرر نفس كويزاته وبالتالي الطلاب قريبين جدا من بعض بالدرجات. لكن بعد كذا صار فيه اولد كويز للدكتور و صار ما يباعد الباقين ممكن يغير لكن مو واجد.\n\nمن ناحية تعامل الدكتور، فهو يحب يذب ويطقطق كثير وبعض الاحيان يستلم ناس معينيين لنهاية الترم ولكنه حبيب جدا.\n\nبشكل عام انصح بالدكتور بالكورس هذا وخاصة ان الكورس 2 credit والدكتور مو معقد الكورس او مخلي جو الكلاس متشنج.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1538554-me218", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-usman-ali/185062/2", "user": "Test101", "ts": 1735330249143, "tid": 185062, "pn": 2}}]}', 1735330249143, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
